const fs = require('fs'), path = require('path');
const DIR = '/tmp/persona';
const USERS_FILE = path.join(DIR, 'users.json');

const sessionId = $input.first().json.sessionId;
const userMessage = $input.first().json.chatInput;

let data = { users: {}, sessions: {} };
if (fs.existsSync(USERS_FILE)) {
  try { data = JSON.parse(fs.readFileSync(USERS_FILE, 'utf8')); } catch(e) {}
}

let isAuthenticated = false, loggedInAs = null, profileInfo = 'none';
const session = data.sessions[sessionId];
if (session && new Date(session.expires) > new Date()) {
  isAuthenticated = true;
  loggedInAs = session.username;
  const u = data.users[loggedInAs];
  if (u) profileInfo = 'email=' + (u.email||'not set') + ', topics=' + (u.topics.join(',')||'none') + ', schedule=' + (u.schedule_time||'not set') + ', active=' + u.active;
}

const histFile = path.join(DIR, 'hist_' + sessionId + '.json');
let history = [];
if (fs.existsSync(histFile)) {
  try { history = JSON.parse(fs.readFileSync(histFile, 'utf8')); } catch(e) {}
}

const intentSystemPrompt = `You are an intent classifier for Persona, a newsletter chatbot.
Return ONLY a valid JSON object, no explanation.

Current state:
- Session: ${sessionId}
- Authenticated: ${isAuthenticated}${isAuthenticated ? ' as ' + loggedInAs + ' | ' + profileInfo : ''}

JSON format: {"action":"ACTION_NAME","params":{...}}

Actions:
- none — just chatting, no operation needed. NOTE: if the user asks about their topics, email, schedule, or profile, use get_profile instead of none
- register — params: {"username":"...","password":"...","email":"..."(optional)}
- login — params: {"username":"...","password":"..."}
- logout — params: {}
- get_profile — params: {}
- update_topics — params: {"topics":"technology,science,...", "mode":"replace" or "add" or "remove"} — use mode "add" when user wants to ADD to existing topics, mode "remove" when user wants to REMOVE specific topics, mode "replace" when user wants to SET all topics. When user says "add all" use all valid topics with mode "replace". Valid: technology,science,world,business,health,politics,sports,entertainment,climate
- update_email — params: {"email":"..."}
- update_schedule — params: {"time":"HH:MM","days":"mon,tue,...","timezone":"..."(optional)}
- request_newsletter — params: {}
- unsubscribe — params: {}
- delete_account — params: {"confirm":"DELETE"}

If required params are missing, use action "none".
Only register and login work without authentication.`;

return [{
  json: {
    sessionId, userMessage, histFile, history, isAuthenticated, loggedInAs,
    intentMessages: [
      { role: 'system', content: intentSystemPrompt },
      ...history,
      { role: 'user', content: userMessage }
    ]
  }
}];

const fs = require('fs'), path = require('path'), crypto = require('crypto');
const DIR = '/tmp/persona';
const USERS_FILE = path.join(DIR, 'users.json');
const PENDING_FILE = path.join(DIR, 'pending.json');

const intentRaw = $input.first().json.choices[0].message.content;
const ctx = $('Build Context').first().json;
const { sessionId, userMessage, histFile, history, isAuthenticated, loggedInAs } = ctx;

let action = 'none', params = {};
try { const p = JSON.parse(intentRaw); action = p.action||'none'; params = p.params||{}; } catch(e) {}

const load = () => {
  if (!fs.existsSync(DIR)) fs.mkdirSync(DIR,{recursive:true});
  if (!fs.existsSync(USERS_FILE)){const d={users:{},sessions:{}};fs.writeFileSync(USERS_FILE,JSON.stringify(d,null,2));return d;}
  try{return JSON.parse(fs.readFileSync(USERS_FILE,'utf8'));}catch(e){return{users:{},sessions:{}};}
};
const save = d => {if(!fs.existsSync(DIR))fs.mkdirSync(DIR,{recursive:true});fs.writeFileSync(USERS_FILE,JSON.stringify(d,null,2));};
const auth = (d,sid) => {const s=d.sessions[sid];if(!s)return null;if(new Date(s.expires)<new Date()){delete d.sessions[sid];save(d);return null;}return s.username;};

let opResult = '';

if (action !== 'none') {
  const d = load();
  if (action === 'register') {
    const u=(params.username||'').trim(), pw=params.password||'', em=(params.email||'').trim();
    if(!u||!pw) opResult='Error: username and password are required.';
    else if(!/^[a-zA-Z0-9_-]{3,20}$/.test(u)) opResult='Error: username must be 3-20 alphanumeric characters.';
    else if(pw.length<8) opResult='Error: password must be at least 8 characters.';
    else if(em&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(em)) opResult='Error: invalid email format.';
    else if(d.users[u.toLowerCase()]) opResult='Error: username already taken.';
    else {
      const salt=crypto.randomBytes(16).toString('hex');
      const hash=crypto.pbkdf2Sync(pw,salt,10000,64,'sha256').toString('hex');
      d.users[u.toLowerCase()]={display_name:u,password:salt+':'+hash,email:em||null,topics:[],schedule_time:null,schedule_days:['mon','tue','wed','thu','fri'],timezone:'UTC',active:false,gdpr_consent:true,gdpr_consent_date:new Date().toISOString(),created_at:new Date().toISOString(),last_newsletter:null};
      save(d); opResult='Success: account created for "'+u+'". GDPR notice: your email (if provided) is stored only for newsletter delivery. You can unsubscribe or delete your account at any time.';
    }
  }
  else if (action === 'login') {
    const u=(params.username||'').toLowerCase(), pw=params.password||'';
    const user=d.users[u];
    if(!user) opResult='Error: invalid username or password.';
    else {
      const [salt,hash]=user.password.split(':');
      const test=crypto.pbkdf2Sync(pw,salt,10000,64,'sha256').toString('hex');
      if(test!==hash) opResult='Error: invalid username or password.';
      else {
        d.sessions[sessionId]={username:u,expires:new Date(Date.now()+6*3600000).toISOString()};
        save(d);
        opResult='Success: logged in as "'+user.display_name+'". Topics: '+(user.topics.join(', ')||'not set')+'. Email: '+(user.email||'not set')+'. Schedule: '+(user.schedule_time||'not set')+'.';
      }
    }
  }
  else if (action === 'logout') {
    if(d.sessions[sessionId]){delete d.sessions[sessionId];save(d);opResult='Success: logged out.';}
    else opResult='No active session.';
  }
  else if (action === 'get_profile') {
    const un=auth(d,sessionId);
    if(!un) opResult='Error: not authenticated.';
    else {const u=d.users[un];opResult='Profile: '+JSON.stringify({username:un,email:u.email,topics:u.topics,schedule:u.schedule_time,days:u.schedule_days,active:u.active,last_newsletter:u.last_newsletter},null,2);}
  }
  else if (action === 'update_topics') {
    const un=auth(d,sessionId);
    if(!un) opResult='Error: not authenticated.';
    else {
      const VALID=['technology','science','world','business','health','politics','sports','entertainment','climate'];
      const incoming=String(params.topics||'').split(',').map(t=>t.trim().toLowerCase()).filter(t=>VALID.includes(t));
      if(!incoming.length) opResult='Error: no valid topics. Valid: '+VALID.join(', ');
      else {
        const mode=params.mode||'replace';
        const existing=d.users[un].topics||[];
        let final;
        if(mode==='add') final=[...new Set([...existing,...incoming])];
        else if(mode==='remove') final=existing.filter(t=>!incoming.includes(t));
        else final=incoming;
        if(mode==='remove'&&final.length===0){opResult='Error: cannot remove all topics, at least one required.';}
        else {
          d.users[un].topics=final;
          if(d.users[un].email&&d.users[un].schedule_time)d.users[un].active=true;
          save(d);
          const check=JSON.parse(fs.readFileSync(USERS_FILE,'utf8'));
          const saved=check.users[un]?.topics||[];
          opResult='Success: topics '+(mode==='add'?'added':mode==='remove'?'removed':'set')+', now: '+saved.join(', ')+'. Newsletter active: '+d.users[un].active;
        }
      }
    }
  }
  else if (action === 'update_email') {
    const un=auth(d,sessionId);
    if(!un) opResult='Error: not authenticated.';
    else if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(params.email||'')) opResult='Error: invalid email format.';
    else {d.users[un].email=params.email;if(d.users[un].topics.length&&d.users[un].schedule_time)d.users[un].active=true;save(d);opResult='Success: email set to '+params.email+'. Newsletter active: '+d.users[un].active;}
  }
  else if (action === 'update_schedule') {
    const un=auth(d,sessionId);
    if(!un) opResult='Error: not authenticated.';
    else if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(params.time||'')) opResult='Error: time must be HH:MM format.';
    else {
      const DAYS=['mon','tue','wed','thu','fri','sat','sun'];
      const days=String(params.days||'mon,tue,wed,thu,fri').split(',').map(x=>x.trim().toLowerCase()).filter(x=>DAYS.includes(x));
      const prevTime=d.users[un].schedule_time;
      d.users[un].schedule_time=params.time;
      d.users[un].schedule_days=days;
      if(params.timezone)d.users[un].timezone=params.timezone;
      if(prevTime!==params.time)d.users[un].last_newsletter=null;
      if(d.users[un].email&&d.users[un].topics.length)d.users[un].active=true;
      save(d);
      opResult='Success: schedule set to '+params.time+' on '+days.join(', ')+(prevTime!==params.time?' (last_newsletter reset, will send at new time today if due)':'')+'. Newsletter active: '+d.users[un].active;
    }
  }
  else if (action === 'request_newsletter') {
    const un=auth(d,sessionId);
    if(!un) opResult='Error: not authenticated.';
    else if(!d.users[un].email) opResult='Error: please set your email first.';
    else if(!d.users[un].topics.length) opResult='Error: please set your topics first.';
    else {
      let p=[];if(fs.existsSync(PENDING_FILE)){try{p=JSON.parse(fs.readFileSync(PENDING_FILE,'utf8'));}catch(e){}}
      if(!p.includes(un)){p.push(un);fs.writeFileSync(PENDING_FILE,JSON.stringify(p,null,2));}
      try{
        const http=require('http');
        const req=http.request({hostname:'localhost',port:5678,path:'/webhook/persona-send-newsletter',method:'POST',headers:{'Content-Type':'application/json'}},()=>{});
        req.on('error',()=>{});
        req.write(JSON.stringify({trigger:'chat',username:un}));
        req.end();
      }catch(e){}
      opResult='Success: newsletter triggered for '+d.users[un].email+'. It will arrive in about a minute.';
    }
  }
  else if (action === 'unsubscribe') {
    const un=auth(d,sessionId);
    if(!un) opResult='Error: not authenticated.';
    else {d.users[un].active=false;save(d);opResult='Success: unsubscribed. Account preserved. Use delete_account to erase all data (GDPR Article 17).';}
  }
  else if (action === 'delete_account') {
    if(params.confirm!=='DELETE') opResult='To confirm permanent deletion, set confirm to exactly "DELETE". This cannot be undone (GDPR Article 17).';
    else {
      const un=auth(d,sessionId);
      if(!un) opResult='Error: not authenticated.';
      else {const name=d.users[un].display_name;delete d.users[un];delete d.sessions[sessionId];save(d);opResult='Success: account "'+name+'" permanently deleted. GDPR Article 17.';}
    }
  }
}

const replySystemPrompt = 'You are Persona, a newsletter assistant. Respond naturally to the user based on the operation result.\nBe concise and helpful. Respond in the user language.\nIf the result starts with Error:, explain the problem and how to fix it.\nIf the result starts with Success:, confirm and guide the user to the next step.\nIf action was none, just chat helpfully.\nNever mention technical details like session IDs or JSON.\nIMPORTANT: Do NOT invent features that do not exist. There is no email confirmation system, no admin panel, no payment system, no public profiles. Only these features exist: register, login, logout, view profile, set topics, set email, set schedule, request newsletter, unsubscribe, delete account.';

const replyMessages = [
  { role: 'system', content: replySystemPrompt },
  ...history,
  { role: 'user', content: userMessage },
  { role: 'assistant', content: opResult || '(no operation performed)' },
  { role: 'user', content: 'Based on the above result, write your response to the user.' }
];

return [{ json: { sessionId, userMessage, histFile, history, action, opResult, replyMessages } }];

const fs = require('fs');
const reply = $input.first().json.choices[0].message.content;
const ctx = $('Execute Operation').first().json;
const { sessionId, userMessage, histFile, history } = ctx;

try {
  const newHist = [
    ...history,
    { role: 'user', content: userMessage },
    { role: 'assistant', content: reply }
  ].slice(-20);
  fs.writeFileSync(histFile, JSON.stringify(newHist, null, 2));
} catch(e) {}

return [{ json: { text: reply } }];
